function MyPromise(executor) {
  this.__state = 'pending'
  this.__value = undefined
  this.__cbs = []

  const resolve = (value) => resolvePromise(this, value)
  const reject = (reason) => settle(this, 'rejected', reason)

  try {
    executor(resolve, reject)
  } catch (e) {
    reject(e)
  }
